export function initMimpi() {
  if (document.getElementById('mimpi-body').children.length > 0) return;

  var currentPage = 1;
  var perPage = 20;
  var filteredData = [];

  function renderTable() {
    var start = (currentPage - 1) * perPage;
    var end = Math.min(start + perPage, filteredData.length);
    var tbody = document.getElementById('mimpi-body');
    var html = '';
    for (var i = start; i < end; i++) {
      var d = filteredData[i];
      html += '<tr><td style="padding:8px 12px;border-bottom:1px solid var(--border-subtle);">' + d.no + '</td><td style="padding:8px 12px;border-bottom:1px solid var(--border-subtle);"><strong>' + d.judul + '</strong></td><td style="padding:8px 12px;border-bottom:1px solid var(--border-subtle);font-family:Courier New,monospace;font-weight:700;color:var(--primary);font-size:15px;">' + d.angka + '</td><td style="padding:8px 12px;border-bottom:1px solid var(--border-subtle);color:var(--text-muted);font-size:12px;line-height:1.5;">' + d.arti + '</td></tr>';
    }
    tbody.innerHTML = html;
    renderPagination();
  }

  function renderPagination() {
    var totalPages = Math.ceil(filteredData.length / perPage);
    var pag = document.getElementById('mimpi-pagination');
    if (totalPages <= 1) { pag.innerHTML = ''; return; }
    var html = '';
    html += '<button data-page="1" style="padding:6px 12px;background:var(--bg-elevated);border:1px solid var(--border-subtle);border-radius:6px;color:var(--text);font-size:12px;cursor:pointer;' + (currentPage === 1 ? 'opacity:.4;cursor:default;' : '') + '">�</button>';
    html += '<button data-page="' + (currentPage - 1) + '" style="padding:6px 12px;background:var(--bg-elevated);border:1px solid var(--border-subtle);border-radius:6px;color:var(--text);font-size:12px;cursor:pointer;' + (currentPage === 1 ? 'opacity:.4;cursor:default;' : '') + '">�</button>';
    html += '<span style="font-size:12px;color:var(--text-muted);padding:0 8px;">Halaman ' + currentPage + ' dari ' + totalPages + '</span>';
    html += '<button data-page="' + (currentPage + 1) + '" style="padding:6px 12px;background:var(--bg-elevated);border:1px solid var(--border-subtle);border-radius:6px;color:var(--text);font-size:12px;cursor:pointer;' + (currentPage === totalPages ? 'opacity:.4;cursor:default;' : '') + '">�</button>';
    html += '<button data-page="' + totalPages + '" style="padding:6px 12px;background:var(--bg-elevated);border:1px solid var(--border-subtle);border-radius:6px;color:var(--text);font-size:12px;cursor:pointer;' + (currentPage === totalPages ? 'opacity:.4;cursor:default;' : '') + '">�</button>';
    pag.innerHTML = html;
  }

  function goPage(p) {
    currentPage = p;
    renderTable();
  }

  function cariMimpi() {
    var q = document.getElementById('mimpi-search').value.toLowerCase().trim();
    var filter = document.getElementById('mimpi-filter').value;
    filteredData = dataMimpi.filter(function(d) {
      var match = true;
      if (q) {
        match = d.judul.toLowerCase().includes(q) || d.arti.toLowerCase().includes(q) || d.angka.includes(q);
      }
      if (match && filter) {
        var parts = filter.split('-');
        var min = parseInt(parts[0]);
        var max = parseInt(parts[1]);
        var ang = parseInt(d.angka);
        match = ang >= min && ang <= max;
      }
      return match;
    });
    currentPage = 1;
    renderTable();
  }

  document.getElementById('mimpi-search').addEventListener('input', cariMimpi);
  document.getElementById('mimpi-filter').addEventListener('change', cariMimpi);
  document.getElementById('mimpi-pagination').addEventListener('click', function(e) {
    var btn = e.target.closest('button[data-page]');
    if (btn && !btn.disabled) goPage(parseInt(btn.dataset.page));
  });

  cariMimpi();
}
